import { L, localize, t, formatMoney, getLanguage } from './i18n.js';
import { loadState, saveState, patchBooking, addToCart, updateCart } from './state.js';
import { journeys, experiences, workshops, products } from '../data/catalog.js';
import { roomTypes, themes } from '../data/rooms.js';
import { imageAssets } from '../data/images.js';
import { galleryCategories, galleryItems } from '../data/gallery.js';

const c = (en, zhCN, zhTW = zhCN) => localize(L(en, zhCN, zhTW));
const root = document.querySelector('[data-prototype-root]');
const page = document.body.dataset.page;
const slug = document.body.dataset.slug;
const imageAlt = item => `${localize(item.name)} — ${c('watercolor concept artwork','水彩概念图','水彩概念圖')}`;
const plainText = value => String(value).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const button = (href, label, style = 'solid') => `<a class="button button--${style}" href="${href}">${label}</a>`;
const hero = ({ eyebrow, title, lead, image, alt }) => `<section class="prototype-hero"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${lead}</p></div><img src="${image}" alt="${alt || `${plainText(title)} — ${c('watercolor concept artwork','水彩概念图','水彩概念圖')}`}" fetchpriority="high" decoding="async"></section>`;

function addJourney(slug) {
  const state = loadState(); state.selectedJourney = slug; state.reservation = null; state.booking = { ...state.booking, journey: slug, step: state.booking.room ? 3 : 0 }; saveState(state); window.location.href = `/book/?journey=${slug}`;
}
function addExperience(slug, price) {
  const state = loadState(); const items = new Set(state.booking.experiences || []); items.add(slug); state.booking = { ...state.booking, experiences: [...items] }; saveState(state);
  const status = document.querySelector('[data-status]'); if (status) status.textContent = c(`Added to your stay · ${formatMoney(price)}`, `已加入住宿 · ${formatMoney(price)}`, `已加入住宿 · ${formatMoney(price)}`);
}

function renderJourneys() {
  root.innerHTML = `${hero({ eyebrow:c('Curated travel routes','酒店策划路线','酒店策劃路線'), title:c('Explore Coloane','探索路环','探索路環'), lead:c('Curated journeys beyond your room. The hotel becomes a quiet starting point for discovering Coloane.','离开客房，继续探索。酒店是发现路环的安静起点。','離開客房，繼續探索。酒店是發現路環的安靜起點。'), image:'/public/images/journeys/nature-escape.webp' })}
  <section class="section prototype-intro"><p class="eyebrow">${c('Two ways beyond the room','两种客房之外的旅程','兩種客房之外的旅程')}</p><h2>${c('The Stay Does Not End at the Room','住宿不止于客房','住宿不止於客房')}</h2></section>
  <section class="section journey-catalog">${journeys.map(j=>`<article><img src="${j.image}" alt="${imageAlt(j)}" loading="lazy" decoding="async"><div><span>${j.number}</span><p class="eyebrow">${localize(j.duration)} · ${formatMoney(j.price)} / 2 ${c('guests','位宾客','位賓客')}</p><h2>${localize(j.name)}</h2><p>${localize(j.tagline)}</p><p class="catalog-price-note">${c('Child supplement','儿童附加费','兒童附加費')}: ${formatMoney(j.childPrice)}</p><div class="button-row">${button(`/journeys/${j.slug}/`, c('Explore Journey','探索旅程'),'outline')}<button class="button button--solid" data-add-journey="${j.slug}">${t('common.addStay')}</button></div></div></article>`).join('')}</section>`;
  root.querySelectorAll('[data-add-journey]').forEach(b=>b.addEventListener('click',()=>addJourney(b.dataset.addJourney)));
}

function renderJourneyDetail() {
  const j = journeys.find(x=>x.slug===slug) || journeys[0]; document.title=`${localize(j.name)} | Pousada do Silêncio`;
  const workshopPanel=j.slug==='cultural-discovery'?`<section class="section workshop-upgrade" id="workshops"><div><p class="eyebrow">${c('Included workshop choice','包含一项手作选择','包含一項手作選擇')}</p><h2>${c('Choose the Craft That Shapes Your Day','选择塑造旅程的手作','選擇塑造旅程的手作')}</h2><p>${c('The standard package includes one of the first three workshops. Traditional Incense replaces the included workshop and changes the total package price to MOP 920 for two guests — it is not added on top of MOP 580.','标准套餐包含前三项手作中的一项。选择传统香文化特别体验后，将替代原有手作，双人套餐总价变为澳门币 920 元，不会在 580 元基础上重复加收。','標準套餐包含前三項手作中的一項。選擇傳統香文化特別體驗後，將替代原有手作，雙人套餐總價變為澳門幣 920 元，不會在 580 元基礎上重複加收。')}</p></div><div class="workshop-option-grid">${j.workshopOptions.map(w=>`<a href="/book/?journey=cultural-discovery&workshop=${w.id}" class="workshop-option"><strong>${localize(w.name)}</strong><span>${w.special?`${formatMoney(j.upgradePrice)} / 2 ${c('guests total','位宾客总价','位賓客總價')}`:c('Included in the MOP 580 package','包含于澳门币 580 元套餐','包含於澳門幣 580 元套餐')}</span>${w.special?`<small>${c('Limited monthly availability','每月限量供应','每月限量供應')}</small>`:''}</a>`).join('')}</div></section>`:'';
  root.innerHTML = `<section class="journey-detail-hero journey-detail-hero--${j.slug}">
    <figure class="journey-detail-hero__media"><img src="${j.image}" alt="${imageAlt(j)}" fetchpriority="high" decoding="async"></figure>
    <div class="journey-detail-hero__panel">
      <p class="eyebrow">${j.number} · ${c('Curated journey','策划旅程','策劃旅程')} · ${localize(j.duration)}</p>
      <h1>${localize(j.name)}</h1>
      <p class="journey-detail-hero__lead">${localize(j.story)}</p>
      <div class="journey-detail-hero__price"><span>${c('Journey supplement','旅程附加费用','旅程附加費用')}</span><strong>${formatMoney(j.price)} / 2 ${c('guests','位宾客','位賓客')}</strong><small>${c('Child supplement','儿童附加费','兒童附加費')}: ${formatMoney(j.childPrice)}</small></div>
      <div class="button-row"><a class="button button--outline" href="#journey-route">${c('Explore Journey','探索旅程')}</a><button class="button button--solid" data-add-journey="${j.slug}">${t('common.addStay')}</button></div>
    </div>
  </section>
  <section class="section detail-ledger detail-ledger--availability"><div><p class="eyebrow">${c('Availability','供应情况','供應情況')}</p><p>${localize(j.availability)}</p></div></section>
  <section class="section route-section" id="journey-route"><div><p class="eyebrow">${c('Illustrated route','插画路线','插畫路線')}</p><h2>${c('A Day Written Across Coloane','写在路环的一天','寫在路環的一天')}</h2></div><ol class="route-line">${j.route.map((stop,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><strong>${localize(stop)}</strong><p>${c('Pause, notice the surroundings, and continue at your own pace.','停下来观察周围，再按自己的节奏继续。','停下來觀察周圍，再按自己的節奏繼續。')}</p></li>`).join('')}</ol></section>
  <section class="included-section"><div class="section"><div><p class="eyebrow">${c("What's included",'包含内容','包含內容')}</p><h2>${c('Prepared for the Journey','为旅程准备','為旅程準備')}</h2></div><ul>${j.included.map(x=>`<li>✓ ${localize(x)}</li>`).join('')}</ul></div></section>${workshopPanel}
  <section class="section practical-note"><h3>${c('Practical information','实用信息','實用資訊')}</h3><p>${localize(j.availability)}</p><p>${c('This is a functional prototype using simulated availability. Final timing and access are confirmed before the stay.','本功能原型使用模拟供应情况。最终时间与通行安排将在入住前确认。','本功能原型使用模擬供應情況。最終時間與通行安排將在入住前確認。')}</p></section>`;
  root.querySelector('[data-add-journey]').addEventListener('click',()=>addJourney(j.slug));
}

function renderExperiences() {
  root.innerHTML = `${hero({eyebrow:c('Small rituals and cultural encounters','小仪式与文化相遇','小儀式與文化相遇'),title:c('Experiences in Coloane','路环体验','路環體驗'),lead:c('Book an individual activity or find it already included within a selected journey.','可单独预订活动，也可在指定旅程中体验。','可單獨預訂活動，也可在指定旅程中體驗。'),image:'/public/images/experiences/cultural-craft-workshop.webp'})}
  <section class="section experience-catalog">${experiences.map((x,i)=>`<article id="${x.slug}"><img src="${x.image}" alt="${imageAlt(x)}" loading="lazy" decoding="async"><div><p class="eyebrow">0${i+1} · ${formatMoney(x.price)}</p><h2>${localize(x.name)}</h2><p>${localize(x.description)}</p><button class="button button--outline" data-add-experience="${x.slug}" data-price="${x.price}">${t('common.addStay')}</button></div></article>`).join('')}</section>
  <section class="section complimentary-note" id="nature-notes"><img src="${imageAssets.scentWalk.filename}" alt="${imageAssets.scentWalk.alt}" loading="lazy"><div><p class="eyebrow">${c('A complimentary way of noticing','一份免费的观察提示','一份免費的觀察提示')}</p><h2>${c('Nature Notes, Not a Paid Product','自然观察，而非付费产品','自然觀察，而非付費產品')}</h2><p>${c('Guests may use the hotel’s quiet prompts to notice leaves, salt air and timber during self-guided exploration. This is descriptive guidance only and carries no standalone charge.','宾客可在自助探索中使用酒店的安静提示，留意叶片、海风与木材气息。这仅为描述性指引，不作为单独收费项目。','賓客可在自助探索中使用酒店的安靜提示，留意葉片、海風與木材氣息。這僅為描述性指引，不作為單獨收費項目。')}</p></div></section><section class="workshop-calendar"><div class="section"><div class="prototype-intro"><p class="eyebrow">${c('Prototype schedule','拟议时间表','擬議時間表')}</p><h2>${c('Workshop Calendar','手作坊日历','手作坊日曆')}</h2><p>${t('common.proposed')}</p></div><div class="session-grid">${workshops.map(w=>`<button data-session="${w.id}" aria-pressed="false"><span>${localize(w.day)}</span><strong>${localize(w.name)}</strong><small>${w.time} · ${formatMoney(w.price)} · ${w.seats} ${c('seats','个名额','個名額')}</small></button>`).join('')}</div><p data-status role="status"></p></div></section>`;
  root.querySelectorAll('[data-add-experience]').forEach(b=>b.addEventListener('click',()=>addExperience(b.dataset.addExperience,Number(b.dataset.price))));
  root.querySelectorAll('[data-session]').forEach(b=>b.addEventListener('click',()=>{ const w=workshops.find(x=>x.id===b.dataset.session); root.querySelectorAll('[data-session]').forEach(x=>x.setAttribute('aria-pressed',String(x===b))); const state=loadState(); const selected=new Set(state.booking.experiences||[]); selected.delete('craft-workshop');selected.delete('traditional-incense-individual');selected.add(w.id==='first-sun-special'?'traditional-incense-individual':'craft-workshop'); state.selectedWorkshop=w.id; state.booking={...state.booking,individualWorkshop:w.id,experiences:[...selected]}; saveState(state); root.querySelector('[data-status]').textContent=c(`${localize(w.name)} selected and added to your stay.`,`${localize(w.name)}已选择并加入住宿。`,`${localize(w.name)}已選擇並加入住宿。`); }));
}

function renderScentQuiz() {
  const questions = [
    { q:c('What kind of atmosphere helps you slow down?','哪种氛围最能让你慢下来？','哪種氛圍最能讓你慢下來？'), a:[['forest',c('Forest','山林')],['sea',c('Coast','海岸')],['nostalgia',c('Warm Nostalgia','温暖旧时光','溫暖舊時光')],['free',c('Neutral & fragrance-free','中性无香','中性無香')]] },
    { q:c('Which scene feels like your ideal Coloane morning?','哪幅画面最像你理想的路环清晨？','哪幅畫面最像你理想的路環清晨？'), a:[['forest',c('Walking under green trees','漫步绿荫下','漫步綠蔭下')],['sea',c('Looking toward the sea','眺望海面')],['nostalgia',c('Wandering old streets','漫步老街')],['free',c('Resting in a calm room','在安静客房休息','在安靜客房休息')]] },
    { q:c('Which experience appeals most?','哪种体验最吸引你？','哪種體驗最吸引你？'), a:[['forest',c('Nature','自然')],['sea',c('Coast','海岸')],['nostalgia',c('Culture & heritage','文化与历史','文化與歷史')],['free',c('Quiet accommodation','安静住宿','安靜住宿')]] },
    { q:c('How do you feel about fragrance?','你对香气的感受是？','你對香氣的感受是？'), a:[['forest',c('I enjoy fragrance','我喜欢香气','我喜歡香氣')],['sea',c('I prefer something subtle','我偏好淡雅香气','我偏好淡雅香氣')],['free',c('I am fragrance-sensitive','我对香气敏感','我對香氣敏感')],['free',c('I prefer no added fragrance','我偏好不添加香气','我偏好不添加香氣')]] }
  ]; let step=0; const scores={forest:0,sea:0,nostalgia:0,free:0};
  root.innerHTML=`${hero({eyebrow:c('A signature hotel experience','酒店标志体验','酒店標誌體驗'),title:c('Find Your Coloane Scent','寻找你的路环香气','尋找你的路環香氣'),lead:c('Let Coloane guide you to your stay.','让路环引导你找到合适的住宿。','讓路環引導你找到合適的住宿。'),image:'/public/images/rooms/sea-breeze-room.webp'})}<section class="section quiz" data-quiz></section>`;
  const quiz=root.querySelector('[data-quiz]');
  const draw=()=>{ const item=questions[step]; quiz.innerHTML=`<p class="quiz__progress">${String(step+1).padStart(2,'0')} / 04</p><h2>${item.q}</h2><div class="quiz__choices">${item.a.map(([key,label],i)=>`<button data-answer="${key}"><span>0${i+1}</span><strong>${label}</strong></button>`).join('')}</div>`; quiz.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{scores[b.dataset.answer]++;step++;step<questions.length?draw():result();})); };
  const result=()=>{ const key=Object.entries(scores).sort((a,b)=>b[1]-a[1])[0][0]; const resultKey=key==='sea'?'sea-breeze':key==='free'?'fragrance-free':key; const theme=themes.find(x=>x.key===resultKey) || themes[0]; const image=key==='free'?roomTypes[0].image:theme.image; const resultAlt=key==='free'?c('Fragrance-Free King watercolor room recommendation','无香大床房水彩客房推荐','無香大床房水彩客房推薦'):`${localize(theme.name)} — ${c('watercolor room atmosphere','水彩客房氛围','水彩客房氛圍')}`; const journey=key==='nostalgia'?'cultural-discovery':'nature-escape'; const state=loadState(); state.scentResult=resultKey; state.booking={...state.booking,room:key==='free'?'king-fragrance-free':state.booking.room,theme:key==='free'?'none':resultKey,fragrance:key==='free'?'fragrance-free':'recommended'}; saveState(state); const bookingQuery=key==='free'?'room=king-fragrance-free&theme=none&fragrance=fragrance-free':`room=king&theme=${resultKey}`; quiz.innerHTML=`<div class="quiz-result"><img src="${image}" alt="${resultAlt}" decoding="async"><div><p class="eyebrow">${c('Your Coloane direction','你的路环方向','你的路環方向')}</p><h2>${key==='free'?c('Fragrance-Free King','无香大床房','無香大床房'):localize(theme.name)}</h2><p>${key==='free'?c('A calm neutral room is your strongest starting point. Fragrance-free accommodation does not limit the journeys or non-fragrance experiences you may enjoy.','安静中性的客房最适合你。无香住宿不会限制你参加旅程或其他无香体验。','安靜中性的客房最適合你。無香住宿不會限制你參加旅程或其他無香體驗。'):c('This atmosphere reflects the pace and scenes you chose. Fragrance remains a separate and optional preference.','这一氛围回应你选择的节奏与画面，香气仍是独立且可选的偏好。','這一氛圍回應你選擇的節奏與畫面，香氣仍是獨立且可選的偏好。')}</p><p><strong>${c('Related journey','相关旅程','相關旅程')}:</strong> ${localize(journeys.find(j=>j.slug===journey).name)}</p><div class="button-row">${button(`/rooms/king/?theme=${key==='free'?'forest':resultKey}${key==='free'?'&fragrance=free':''}`,c('Explore Recommended Rooms','探索推荐客房','探索推薦客房'),'outline')}${button(`/book/?${bookingQuery}`,c('Continue to Booking','继续预订','繼續預訂'))}</div></div></div>`; };
  draw();
}

function renderColoane() {
  const places=[[c('Cheoc Van Beach','竹湾海滩','竹灣海灘'),c('Coast → Sea Breeze','海岸 → 海风','海岸 → 海風'),imageAssets.cheocVan],[c('Countryside & Trails','乡野与步道','鄉野與步道'),c('Countryside → Forest','乡野 → 山林','鄉野 → 山林'),imageAssets.countryside],[c('Coloane Village','路环市区','路環市區'),c('Historic streets → Nostalgia','历史街巷 → 旧时光','歷史街巷 → 舊時光'),imageAssets.coloaneVillage],[c('Lai Chi Vun Shipyards','荔枝碗船厂片区','荔枝碗船廠片區'),c('Craft → Memory','工艺 → 记忆','工藝 → 記憶'),imageAssets.shipyards]];
  root.innerHTML=`${hero({eyebrow:c('The hotel as a gateway','从酒店出发','從酒店出發'),title:c('Discover the Quiet Side of Macao','发现澳门安静的一面','發現澳門安靜的一面'),lead:c('A hotel perspective on coast, countryside, village streets, local shops and community character.','从酒店视角认识海岸、乡野、村落街巷、本地小店与社区气质。','從酒店視角認識海岸、鄉野、村落街巷、本地小店與社區氣質。'),image:imageAssets.hotelExterior.filename,alt:imageAssets.hotelExterior.alt})}<section class="section place-grid">${places.map(p=>`<article><img src="${p[2].filename}" alt="${p[2].alt}" loading="lazy" decoding="async"><p class="eyebrow">${p[1]}</p><h2>${p[0]}</h2><p>${c('Notice the place slowly, with the hotel’s illustrated journal as a companion.','带着酒店的插画手帐，缓慢观察这里。','帶著酒店的插畫手帳，緩慢觀察這裡。')}</p></article>`).join('')}</section><section class="passport"><div class="section"><div><p class="eyebrow">${c('An exploration tool','探索工具')}</p><h2>${c('Coloane Experience Passport','路环体验护照','路環體驗護照')}</h2><p>${c('A conceptual stamp-style guide connecting hotel guests with participating community locations. Businesses remain conceptual until formally confirmed; no partnership is implied.','概念印章式探索工具，连接酒店宾客与参与的社区地点。商户在正式确认前均为概念示例，不代表已建立合作。','概念印章式探索工具，連接酒店賓客與參與的社區地點。商戶在正式確認前均為概念示例，不代表已建立合作。')}</p></div><figure class="passport-visual"><img src="${imageAssets.experiencePassport.filename}" alt="${imageAssets.experiencePassport.alt}" loading="lazy" decoding="async"><figcaption><span>COAST</span><span>CRAFT</span><span>VILLAGE</span></figcaption></figure></div></section>`;
}

function renderHotel() {
  const spaces=[[c('Portuguese Arcade','葡式拱廊','葡式拱廊'),'51%','88%'],[c('Scent Foyer','气味玄关','氣味玄關'),'51%','67%'],[c('Reception','接待大堂','接待大堂'),'60%','53%'],[c('Reading Lounge','阅读休憩','閱讀休憩'),'43%','53%'],[c('Local Shop','本土小店','本土小店'),'30%','54%'],[c('Sensory Workshop','感官工作坊','感官工作坊'),'51%','12%'],[c('Water Station','饮水站','飲水站'),'76%','58%']];
  const restaurantAlt=c('Watercolor view of the second-floor restaurant with arched windows, Portuguese tiles and the Coloane coast','二楼餐厅水彩图，拱窗、葡式瓷砖与路环海岸相映','二樓餐廳水彩圖，拱窗、葡式瓷磚與路環海岸相映');
  root.innerHTML=`${hero({eyebrow:c('Aromatic eco-boutique hotel · Coloane','芳香生态精品酒店 · 路环','芳香生態精品酒店 · 路環'),title:'Pousada do Silêncio<br><small>竹灣隱舍</small>',lead:c('A proposed four-star boutique leisure hotel connected to Cheoc Van, local craft, optional sensory accommodation, slow travel and community life.','一间拟议四星精品度假酒店，连接竹湾、本地工艺、可选感官住宿、慢旅行与社区生活。','一間擬議四星精品度假酒店，連接竹灣、本地工藝、可選感官住宿、慢旅行與社區生活。'),image:'/public/images/hotel/hotel-exterior.webp'})}
  <section class="section logo-story"><img src="/public/images/brand/logo-lockup.png" alt="Pousada do Silêncio logo"><div><p class="eyebrow">${c('The mark we carry','我们的标志','我們的標誌')}</p><h2>${c('Coast, Bamboo, Scent, Openness','海岸、竹叶、香气、开放','海岸、竹葉、香氣、開放')}</h2><p>${c('Waves hold the coast, bamboo carries nature, a warm line suggests fragrance in motion, and the open circle leaves room for Chinese and Portuguese identity to meet.','海浪承载海岸，竹叶象征自然，暖色线条表现流动香气，开放圆环让中葡身份相遇。','海浪承載海岸，竹葉象徵自然，暖色線條表現流動香氣，開放圓環讓中葡身份相遇。')}</p></div></section>
  <section class="hotel-dining" id="restaurant" aria-labelledby="hotel-dining-title"><div class="section hotel-dining__layout"><div class="hotel-dining__intro"><p class="eyebrow">${c('Second floor · Dining room','二楼 · 餐厅','二樓 · 餐廳')}</p><h2 id="hotel-dining-title">${c('Dining at Pousada','竹湾隐舍餐饮','竹灣隱舍餐飲')}</h2><p class="hotel-dining__lead">${c('The restaurant sits on the hotel’s second floor, opening the dining room to coastal light and the slower rhythm of Coloane.','餐厅位于酒店二楼，让海岸光线与路环缓慢的节奏自然进入用餐空间。','餐廳位於酒店二樓，讓海岸光線與路環緩慢的節奏自然進入用餐空間。')}</p><p>${c('Arched windows, hand-painted Portuguese tiles, woven rattan and warm timber create a relaxed setting that feels inseparable from the hotel around it.','拱形窗、手绘葡式瓷砖、藤编与暖木共同营造轻松氛围，让餐厅与整座酒店自然相连。','拱形窗、手繪葡式瓷磚、藤編與暖木共同營造輕鬆氛圍，讓餐廳與整座酒店自然相連。')}</p></div><figure class="hotel-dining__hero"><img src="/public/images/dining/restaurant-overview.webp" alt="${restaurantAlt}" loading="lazy" decoding="async"><figcaption>${c('An open, unhurried room above the Portuguese arcade','葡式拱廊之上的开阔从容空间','葡式拱廊之上的開闊從容空間')}</figcaption></figure><div class="hotel-dining__notes" aria-label="${c('Restaurant design details','餐厅设计细节','餐廳設計細節')}"><span>${c('Arched coastal windows','临海拱窗','臨海拱窗')}</span><span>${c('Portuguese tilework','葡式瓷砖','葡式瓷磚')}</span><span>${c('Natural timber & rattan','天然木与藤编','天然木與藤編')}</span></div><div class="hotel-dining__details"><figure><img src="/public/images/dining/restaurant-window-table.webp" alt="${c('Restaurant table beside an arched window overlooking the Coloane coast','拱窗旁俯瞰路环海岸的餐桌','拱窗旁俯瞰路環海岸的餐桌')}" loading="lazy" decoding="async"><figcaption><strong>${c('A Table by the Coast','海岸窗边一席','海岸窗邊一席')}</strong><span>${c('Soft daylight, hand-painted ceramics and a quiet view toward the chapel.','柔和日光、手绘陶瓷与远眺小教堂的安静景致。','柔和日光、手繪陶瓷與遠眺小教堂的安靜景致。')}</span></figcaption></figure><figure><img src="/public/images/dining/restaurant-material-details.webp" alt="${c('Natural wood restaurant buffet with Portuguese ceramics and botanical details','天然木餐边柜、葡式陶瓷与植物细节','天然木餐邊櫃、葡式陶瓷與植物細節')}" loading="lazy" decoding="async"><figcaption><strong>${c('Materials with Memory','承载记忆的材质','承載記憶的材質')}</strong><span>${c('Warm wood, woven light and blue-and-white tile continue the hotel’s Portuguese coastal character.','暖木、藤编灯光与蓝白瓷砖延续酒店的葡式海岸气质。','暖木、藤編燈光與藍白瓷磚延續酒店的葡式海岸氣質。')}</span></figcaption></figure></div></div></section>
  <section class="floor-explorer"><div class="section prototype-intro"><p class="eyebrow">${c('Tap a space','点击空间','點擊空間')}</p><h2>${c('Step Inside Pousada do Silêncio','走进竹湾隐舍','走進竹灣隱舍')}</h2></div><div class="floor-interactive"><img src="/public/images/hotel/ground-floor-plan.webp" alt="${c('Watercolor ground floor plan','一层水彩平面图','一樓水彩平面圖')}">${spaces.map((s,i)=>`<button style="--x:${s[1]};--y:${s[2]}" data-space="${i}" aria-label="${s[0]}">${i+1}</button>`).join('')}<div class="floor-card" data-floor-card><strong>${spaces[0][0]}</strong><p>${c('Select a numbered point to learn how the ground floor supports arrival, rest, craft and exploration.','选择编号地点，了解一层如何承载抵达、休息、工艺与探索。','選擇編號地點，了解一樓如何承載抵達、休息、工藝與探索。')}</p></div></div></section><section class="section practical-note"><h3>${c('Sensory accessibility','感官可及性','感官可及性')}</h3><p>${c('Fragrance experiences are optional. Guests may reach reception without participating in scent displays, and designated fragrance-free King Rooms are available.','香气体验完全可选。宾客无需参与香气展示即可到达接待处，并可选择指定无香大床房。','香氣體驗完全可選。賓客無需參與香氣展示即可到達接待處，並可選擇指定無香大床房。')}</p></section>`;
  root.querySelectorAll('[data-space]').forEach(b=>b.addEventListener('click',()=>{root.querySelectorAll('[data-space]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const s=spaces[Number(b.dataset.space)];root.querySelector('[data-floor-card]').innerHTML=`<strong>${s[0]}</strong><p>${c('A calm, clearly marked part of the hotel’s ground-floor journey.','酒店一层动线中安静且清晰标示的空间。','酒店一樓動線中安靜且清晰標示的空間。')}</p>`;}));
}

function renderShop() {
  root.innerHTML=`${hero({eyebrow:c('The hotel shop, online','酒店商店 · 线上','酒店商店 · 線上'),title:c('Take Coloane Home','把路环带回家','把路環帶回家'),lead:c('Scents, crafts and small memories inspired by your stay.','由住宿启发的香气、工艺与小小记忆。','由住宿啟發的香氣、工藝與小小記憶。'),image:'/public/images/products/shop-collection.webp'})}<section class="section shop-toolbar"><div><button data-filter="all" aria-pressed="true">${c('All','全部')}</button><button data-filter="scent">${c('Scent Collection','香气系列','香氣系列')}</button><button data-filter="craft">${c('Incense & Craft','香文化与工艺','香文化與工藝')}</button><button data-filter="memories">${c('Hotel Memories','酒店记忆','酒店記憶')}</button><button data-filter="fragrance-free">${c('Fragrance-Free Gifts','无香礼品','無香禮品')}</button></div><button class="bag-button" data-open-bag>${c('Bag','购物袋','購物袋')} <span data-bag-count>0</span></button></section><section class="section product-grid" data-products></section><aside class="bag-drawer" data-bag hidden aria-label="${c('Shopping bag','购物袋','購物袋')}"><div><button data-close-bag aria-label="${t('common.close')}">×</button><h2>${c('Your Bag','你的购物袋','你的購物袋')}</h2><div data-bag-items></div><p><span>${t('common.subtotal')}</span><strong data-bag-total></strong></p>${button('/shop/checkout/',t('common.checkout'))}</div></aside>`;
  const grid=root.querySelector('[data-products]'); const drawProducts=(filter='all')=>{grid.innerHTML=products.filter(p=>filter==='all'||p.category===filter).map(p=>`<article><a href="/shop/product/${p.slug}/"><img src="${p.image}" alt="${imageAlt(p)}" loading="lazy" decoding="async"><p class="eyebrow">${p.category.replace('-', ' ')}</p><h3>${localize(p.name)}</h3><p>${formatMoney(p.price)}</p></a><button class="button button--outline" data-cart-add="${p.slug}">${c('Add to Bag','加入购物袋','加入購物袋')}</button></article>`).join('');grid.querySelectorAll('[data-cart-add]').forEach(b=>b.addEventListener('click',()=>{addToCart(b.dataset.cartAdd);drawBag();}));};
  const drawBag=()=>{const state=loadState();root.querySelector('[data-bag-count]').textContent=state.cart.reduce((s,i)=>s+i.quantity,0);root.querySelector('[data-bag-items]').innerHTML=state.cart.length?state.cart.map(i=>{const p=products.find(x=>x.slug===i.slug);return `<div><img src="${p.image}" alt=""><span><strong>${localize(p.name)}</strong><small>${formatMoney(p.price)}</small><label>${t('common.quantity')}<input data-cart-quantity="${i.slug}" type="number" min="1" max="9" value="${i.quantity}"></label></span><button data-remove="${i.slug}">${t('common.remove')}</button></div>`;}).join(''):`<p>${c('Your bag is empty.','购物袋为空。','購物袋為空。')}</p>`;root.querySelector('[data-bag-total]').textContent=formatMoney(state.cart.reduce((s,i)=>s+products.find(p=>p.slug===i.slug).price*i.quantity,0));root.querySelectorAll('[data-cart-quantity]').forEach(input=>input.addEventListener('input',()=>{updateCart(input.dataset.cartQuantity,Math.max(1,Math.min(9,Number(input.value)||1)));drawBag();}));root.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{updateCart(b.dataset.remove,0);drawBag();}));};
  root.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{root.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));drawProducts(b.dataset.filter);}));root.querySelector('[data-open-bag]').addEventListener('click',()=>root.querySelector('[data-bag]').hidden=false);root.querySelector('[data-close-bag]').addEventListener('click',()=>root.querySelector('[data-bag]').hidden=true);drawProducts();drawBag();if(new URLSearchParams(location.search).get('bag')==='open')root.querySelector('[data-bag]').hidden=false;
}

function renderProduct() {
  const p=products.find(x=>x.slug===slug)||products[0]; document.title=`${localize(p.name)} | Pousada do Silêncio`;
  root.innerHTML=`<section class="product-detail"><div class="product-detail__gallery"><img src="${p.image}" alt="${imageAlt(p)}" fetchpriority="high" decoding="async"></div><div><p class="eyebrow">${p.category.replace('-',' ')}</p><h1>${localize(p.name)}</h1><strong>${formatMoney(p.price)}</strong><p>${localize(p.description)}</p>${p.scent?`<p><b>${c('Scent notes','香调','香調')}:</b> ${localize(p.scent)}</p>`:''}${p.safety?`<aside>${c('Open flames are not permitted in hotel guestrooms or indoor hotel workshops. Purchased incense must not be burned inside guestrooms.','酒店客房与室内工作坊禁止明火。购买的香品不得在客房内燃烧。','酒店客房與室內工作坊禁止明火。購買的香品不得在客房內燃燒。')}</aside>`:''}<label>${t('common.quantity')}<input type="number" min="1" max="9" value="1" data-product-qty></label><div class="button-row"><button class="button button--solid" data-product-add>${c('Add to Bag','加入购物袋','加入購物袋')}</button><a class="text-link" href="/shop/?bag=open">${t('common.viewBag')} <span>→</span></a></div><p data-status role="status"></p></div></section><section class="section related-products"><h2>${c('You May Also Like','你可能也喜欢','你可能也喜歡')}</h2><div class="product-grid">${products.filter(x=>x.slug!==p.slug).slice(0,3).map(x=>`<article><a href="/shop/product/${x.slug}/"><img src="${x.image}" alt="${imageAlt(x)}" loading="lazy" decoding="async"><h3>${localize(x.name)}</h3><p>${formatMoney(x.price)}</p></a></article>`).join('')}</div></section>`;
  root.querySelector('[data-product-add]').addEventListener('click',()=>{addToCart(p.slug,Number(root.querySelector('[data-product-qty]').value));root.querySelector('[data-status]').textContent=c('Added to your bag.','已加入购物袋。','已加入購物袋。');});
}

function renderCheckout() {
  let step=0; const state=loadState(); const total=state.cart.reduce((s,i)=>s+(products.find(p=>p.slug===i.slug)?.price||0)*i.quantity,0); const steps=[c('Bag','购物袋','購物袋'),c('Delivery','配送'),c('Payment','付款'),c('Confirmation','确认','確認')];
  root.innerHTML=`<section class="flow-page"><div class="flow-progress">${steps.map((s,i)=>`<span data-flow-step="${i}">${String(i+1).padStart(2,'0')} ${s}</span>`).join('')}</div><div data-checkout-stage></div></section>`; const stage=root.querySelector('[data-checkout-stage]');
  const draw=()=>{root.querySelectorAll('[data-flow-step]').forEach((x,i)=>x.classList.toggle('is-current',i===step)); if(step===0)stage.innerHTML=`<h1>${c('Review Your Bag','检查购物袋','檢查購物袋')}</h1>${state.cart.map(i=>{const p=products.find(x=>x.slug===i.slug);return `<p>${localize(p.name)} × ${i.quantity} <strong>${formatMoney(p.price*i.quantity)}</strong></p>`;}).join('')||`<p>${c('Your bag is empty.','购物袋为空。','購物袋為空。')}</p>`}<h3>${t('common.subtotal')}: ${formatMoney(total)}</h3><button class="button button--solid" data-next ${state.cart.length?'':'disabled'}>${t('common.next')}</button>`; else if(step===1)stage.innerHTML=`<h1>${c('Delivery','配送')}</h1>${state.reservation?`<p>${c('Linked reservation','关联预订','關聯預訂')}: <strong>${state.reservation.number}</strong></p>`:''}<fieldset><legend>${c('Choose an option','选择方式','選擇方式')}</legend>${[['stay',c('Deliver During My Stay','住宿期间送达','住宿期間送達')],['collect',c('Collect at Hotel','酒店领取','酒店領取')],['home',c('Home Delivery','送货到家','送貨到家')]].map((x,i)=>`<label><input type="radio" name="delivery" value="${x[0]}" ${state.shopDelivery===x[0]||(!state.shopDelivery&&i===0)?'checked':''}> ${x[1]}</label>`).join('')}</fieldset><button class="button button--solid" data-next>${t('common.next')}</button>`; else if(step===2)stage.innerHTML=`<form data-payment><h1>${c('Prototype Payment','模拟付款','模擬付款')}</h1><p>${c('No real payment will be processed.','不会处理真实付款。','不會處理真實付款。')}</p><label>${c('Name on card','持卡人姓名')}<input required autocomplete="cc-name"></label><label>${c('Prototype card number','模拟卡号','模擬卡號')}<input inputmode="numeric" placeholder="4242 4242 4242 4242" required aria-describedby="payment-note"></label><small id="payment-note">${c('Use test data only.','仅使用测试数据。','僅使用測試資料。')}</small><button class="button button--solid" data-next>${c('Place Prototype Order','提交模拟订单','提交模擬訂單')}</button></form>`; else {const order=`SHOP-${Date.now().toString().slice(-6)}`;const latest=loadState();latest.shopOrder={number:order,total,delivery:latest.shopDelivery||'stay',items:latest.cart};latest.cart=[];saveState(latest);stage.innerHTML=`<h1>${c('Order Confirmed','订单已确认','訂單已確認')}</h1><p>${c('Prototype order number','模拟订单编号','模擬訂單編號')}: <strong>${order}</strong></p><p>${formatMoney(total)}</p>${button('/shop/',c('Return to Shop','返回商店'))}`;}
    stage.querySelector('[data-next]')?.addEventListener('click',event=>{event.preventDefault();const payment=stage.querySelector('[data-payment]');if(payment&&!payment.reportValidity())return;if(step===1){state.shopDelivery=stage.querySelector('input[name="delivery"]:checked')?.value||'stay';saveState(state);}step++;draw();});};draw();
}

function renderReservation() {
  const state=loadState(),r=state.reservation,order=state.shopOrder;
  const roomNames={king:c('Standard King','标准大床房','標準大床房'),'king-fragrance-free':c('Fragrance-Free King','无香大床房','無香大床房'),twin:c('Twin','双床房','雙床房'),family:c('Family','家庭房'),suite:c('Suite','套房')};
  const legacyRooms={'Standard King':roomNames.king,'标准大床房':roomNames.king,'標準大床房':roomNames.king,'Fragrance-Free King':roomNames['king-fragrance-free'],'无香大床房':roomNames['king-fragrance-free'],'無香大床房':roomNames['king-fragrance-free']};
  const themeNames={forest:c('Forest','山林'),'sea-breeze':c('Sea Breeze','海风','海風'),nostalgia:c('Nostalgia','旧时光','舊時光'),none:c('No preference','无偏好','無偏好')};
  const legacyThemes={Forest:themeNames.forest,山林:themeNames.forest,'Sea Breeze':themeNames['sea-breeze'],海风:themeNames['sea-breeze'],海風:themeNames['sea-breeze'],Nostalgia:themeNames.nostalgia,旧时光:themeNames.nostalgia,舊時光:themeNames.nostalgia};
  const experienceNames=r?.experiences?.map(key=>localize(experiences.find(x=>x.slug===key)?.name||workshops.find(x=>x.id===key)?.name||key))||[];
  const journeyName=r?.journey?localize(journeys.find(x=>x.slug===r.journey)?.name||r.journey):'';
  const culturalJourney=journeys.find(x=>x.slug==='cultural-discovery');
  const workshopName=r?.culturalWorkshop?localize(culturalJourney?.workshopOptions?.find(x=>x.id===r.culturalWorkshop)?.name||r.culturalWorkshop):'';
  const deliveryNames={stay:c('Deliver During My Stay','住宿期间送达','住宿期間送達'),collect:c('Collect at Hotel','酒店领取','酒店領取'),home:c('Home Delivery','送货到家','送貨到家')};
  root.innerHTML=`<section class="flow-page reservation-view"><p class="eyebrow">${c('Prototype reservation','模拟预订','模擬預訂')}</p><h1>${r?c('Your Coloane Journey','你的路环旅程','你的路環旅程'):c('Find Your Reservation','查询预订','查詢預訂')}</h1>${r?`<div class="reservation-card"><strong>${r.number}</strong><p>${r.checkin} → ${r.checkout}</p><p>${roomNames[r.roomKey]||legacyRooms[r.room]||r.room} · ${themeNames[r.themeKey]||legacyThemes[r.theme]||r.theme} · ${r.guests} ${c('guests','位宾客','位賓客')}</p>${journeyName?`<h2>${c('Selected journey','已选旅程','已選旅程')}</h2><p>${journeyName}${workshopName?` · ${workshopName}`:''}</p>`:''}${experienceNames.length?`<h2>${c('Selected experiences','已选体验','已選體驗')}</h2><p>${experienceNames.join(' · ')}</p>`:''}<p>${formatMoney(r.total)}</p>${order?`<hr><h2>${c('Shop delivery','商店配送')}</h2><p>${order.number} · ${deliveryNames[order.delivery]||order.delivery} · ${formatMoney(order.total)}</p>`:''}</div>`:`<form data-reservation-search><label>${c('Confirmation number','确认编号','確認編號')}<input required placeholder="PDS-123456"></label><button class="button button--solid">${c('View Reservation','查看预订','查看預訂')}</button><p data-search-status role="status"></p></form>`}${button('/',c('Return Home','返回首页','返回首頁'),'outline')}</section>`;
  root.querySelector('[data-reservation-search]')?.addEventListener('submit',event=>{event.preventDefault();root.querySelector('[data-search-status]').textContent=c('No matching prototype reservation was found in this browser.','此浏览器中没有匹配的模拟预订。','此瀏覽器中沒有匹配的模擬預訂。');});
}

function renderGallery() {
  let activeCategory='all', visibleItems=[...galleryItems], activeIndex=0, touchStart=0;
  const categoryName=id=>localize(galleryCategories.find(x=>x.id===id)?.name||id);
  root.innerHTML=`${hero({eyebrow:c('The illustrated journal','插画旅行手帐','插畫旅行手帳'),title:c('A Visual Journey Through Coloane','路环视觉旅程','路環視覺旅程'),lead:c('Discover the architecture, nature, quiet moments and cultural details that define Pousada do Silêncio.','发现定义竹湾隐舍的建筑、自然、安静时刻与文化细节。','發現定義竹灣隱舍的建築、自然、安靜時刻與文化細節。'),image:imageAssets.experiencePassport.filename,alt:imageAssets.experiencePassport.alt})}<section class="section gallery-journal"><div class="gallery-filters" role="toolbar" aria-label="${c('Filter gallery','筛选画廊','篩選畫廊')}">${galleryCategories.map((x,i)=>`<button type="button" data-gallery-filter="${x.id}" aria-pressed="${i===0}">${localize(x.name)}</button>`).join('')}</div><p class="gallery-disclosure">${c('Official hotel concept artwork and clearly identified conceptual illustrations are shown together as an evolving visual journal.','官方酒店概念图与清楚标示的概念插画共同构成持续发展的视觉手帐。','官方酒店概念圖與清楚標示的概念插畫共同構成持續發展的視覺手帳。')}</p><div class="gallery-masonry" data-gallery-grid></div></section><dialog class="gallery-lightbox" data-lightbox aria-labelledby="gallery-lightbox-title"><button class="gallery-lightbox__close" data-lightbox-close aria-label="${t('common.close')}">×</button><button class="gallery-lightbox__nav gallery-lightbox__nav--prev" data-lightbox-prev aria-label="${c('Previous image','上一张图片','上一張圖片')}">←</button><figure><img alt=""><figcaption><span data-lightbox-category></span><h2 id="gallery-lightbox-title"></h2><p></p><small data-lightbox-status></small></figcaption></figure><button class="gallery-lightbox__nav gallery-lightbox__nav--next" data-lightbox-next aria-label="${c('Next image','下一张图片','下一張圖片')}">→</button></dialog>`;
  const grid=root.querySelector('[data-gallery-grid]'),dialog=root.querySelector('[data-lightbox]');
  const drawGrid=()=>{visibleItems=galleryItems.filter(x=>activeCategory==='all'||x.category===activeCategory);grid.innerHTML=visibleItems.map((x,i)=>`<button class="gallery-entry gallery-entry--${x.size}" data-gallery="${i}"><img src="${x.asset.filename}" alt="${x.asset.alt}" loading="lazy" decoding="async"><span><small>${categoryName(x.category)}</small><strong>${localize(x.title)}</strong><em>${x.asset.status==='original'?c('Official concept artwork','官方概念图','官方概念圖'):x.asset.status==='user-supplied'?c('Official supplied artwork','官方提供图像','官方提供圖像'):c('Concept illustration','概念插画','概念插畫')}</em></span></button>`).join('');grid.querySelectorAll('[data-gallery]').forEach(b=>b.addEventListener('click',()=>openLightbox(Number(b.dataset.gallery))));};
  const showItem=()=>{const x=visibleItems[activeIndex];dialog.querySelector('img').src=x.asset.filename;dialog.querySelector('img').alt=x.asset.alt;dialog.querySelector('h2').textContent=localize(x.title);dialog.querySelector('p').textContent=localize(x.caption);dialog.querySelector('[data-lightbox-category]').textContent=categoryName(x.category);dialog.querySelector('[data-lightbox-status]').textContent=`${activeIndex+1} / ${visibleItems.length} · ${x.asset.status==='ai-generated'?c('Concept illustration','概念插画','概念插畫'):c('Official artwork','官方图像','官方圖像')}`;};
  const openLightbox=i=>{activeIndex=i;showItem();dialog.showModal();};
  const move=delta=>{activeIndex=(activeIndex+delta+visibleItems.length)%visibleItems.length;showItem();};
  root.querySelectorAll('[data-gallery-filter]').forEach(b=>b.addEventListener('click',()=>{activeCategory=b.dataset.galleryFilter;root.querySelectorAll('[data-gallery-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));drawGrid();}));
  root.querySelector('[data-lightbox-close]').addEventListener('click',()=>dialog.close());root.querySelector('[data-lightbox-prev]').addEventListener('click',()=>move(-1));root.querySelector('[data-lightbox-next]').addEventListener('click',()=>move(1));dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});dialog.addEventListener('keydown',event=>{if(event.key==='ArrowLeft')move(-1);if(event.key==='ArrowRight')move(1);});dialog.addEventListener('pointerdown',event=>{touchStart=event.clientX;});dialog.addEventListener('pointerup',event=>{const distance=event.clientX-touchStart;if(Math.abs(distance)>55)move(distance>0?-1:1);});drawGrid();
}

function renderContact() {
  root.innerHTML=`${hero({eyebrow:c('Practical information','实用信息','實用資訊'),title:c('Plan Your Stay','规划住宿','規劃住宿'),lead:c('Contact details remain clearly marked placeholders until the hotel information is formally confirmed.','酒店资料正式确认前，联系信息均清楚标示为占位内容。','酒店資料正式確認前，聯絡資訊均清楚標示為佔位內容。'),image:'/public/images/hotel/hotel-exterior.webp'})}<section class="section contact-grid"><article><h2>${c('Contact','联系','聯絡')}</h2><p>${c('Address: [To be confirmed], Coloane, Macao','地址：[待确认]，澳门路环','地址：[待確認]，澳門路環')}</p><p>Phone: [To be confirmed]</p><p>Email: [To be confirmed]</p></article><article><h2>${c('Arrival','抵达','抵達')}</h2><p>${c('Transport information and check-in directions will be confirmed before opening.','交通与入住指引将在开业前确认。','交通與入住指引將在開業前確認。')}</p><p>Check-in: [To be confirmed]<br>Check-out: [To be confirmed]</p></article><article><h2>FAQ</h2><details><summary>${c('Is fragrance required?','香气体验是必须的吗？','香氣體驗是必須的嗎？')}</summary><p>${c('No. Fragrance is optional, and designated fragrance-free King Rooms are available.','不是。香气完全可选，并提供指定无香大床房。','不是。香氣完全可選，並提供指定無香大床房。')}</p></details><details><summary>${c('Are journeys guaranteed?','旅程一定能举行吗？','旅程一定能舉行嗎？')}</summary><p>${c('Outdoor routes and workshops are subject to weather, safety, capacity and partner availability.','户外路线与手作坊视天气、安全、名额与合作方供应而定。','戶外路線與手作坊視天氣、安全、名額與合作方供應而定。')}</p></details></article><article id="policies"><h2>${c('Policies','政策')}</h2><p>${c('Booking, cancellation, accessibility, fragrance and shop policies are prototype placeholders and do not represent final hotel terms.','预订、取消、无障碍、香气与商店政策为原型占位，并非最终酒店条款。','預訂、取消、無障礙、香氣與商店政策為原型占位，並非最終酒店條款。')}</p></article></section>`;
}

if(root){({journeys:renderJourneys,'journey-detail':renderJourneyDetail,experiences:renderExperiences,scent:renderScentQuiz,coloane:renderColoane,hotel:renderHotel,shop:renderShop,product:renderProduct,checkout:renderCheckout,reservation:renderReservation,gallery:renderGallery,contact:renderContact}[page]||renderJourneys)();}
